css:
.dbmig-sim-container {
    padding: 28px;
    background: #0a0f1e;
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #e0e6f0;
}

.dbmig-sim-header {
    border-left: 4px solid #00ff88;
    padding: 24px 32px;
    margin-bottom: 24px;
    background: linear-gradient(90deg, rgba(0,255,136,0.10), rgba(0,191,255,0.02));
    border-radius: 0 6px 6px 0;
}

.dbmig-sim-container .dbmig-sim-header h1 {
    color: #00ff88;
    font-size: 1.55rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    margin: 0;
    font-weight: 700;
}

.dbmig-sim-subtitle {
    color: #70829a;
    font-size: 0.85rem;
    margin-top: 8px;
    letter-spacing: 0.04em;
}

.dbmig-sim-period-bar {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 12px 20px;
    margin-bottom: 24px;
    display: flex;
    align-items: center;
    gap: 8px;
    color: #9ca3af;
    font-size: 0.92rem;
}

.dbmig-sim-period-bar .dbmig-sim-round-pill {
    background: #00bfff;
    color: #0a0f1e;
    padding: 5px 14px;
    border-radius: 4px;
    font-weight: 700;
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.10em;
    margin-right: 16px;
}

.dbmig-sim-period-spacer { flex: 1; }

.dbmig-sim-score-badge {
    background: rgba(0,255,136,0.10);
    border: 1px solid rgba(0,255,136,0.3);
    color: #00ff88;
    padding: 5px 12px;
    border-radius: 4px;
    font-weight: 700;
    font-size: 0.85rem;
    letter-spacing: 0.04em;
}

.dbmig-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(190px, 1fr));
    gap: 16px;
    margin-bottom: 24px;
}

.dbmig-sim-kpi-card {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px 20px 20px 20px;
    position: relative;
    overflow: hidden;
    transition: border-color 0.2s ease, transform 0.2s ease;
}

.dbmig-sim-kpi-card:hover {
    border-color: #00ff88;
    transform: translateY(-2px);
}

.dbmig-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 2px;
    background: linear-gradient(90deg, #00ff88, #00bfff);
}

.dbmig-sim-kpi-label {
    color: #70829a;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    margin-bottom: 12px;
}

.dbmig-sim-kpi-value {
    font-size: 2.2rem;
    font-weight: 700;
    color: #00ff88;
    line-height: 1;
    display: inline-block;
}

.dbmig-sim-kpi-suffix {
    display: inline-block;
    color: #70829a;
    font-size: 0.95rem;
    margin-left: 4px;
    font-weight: 500;
}

.dbmig-sim-briefing {
    background: #0d1525;
    border: 1px solid #1f2d3d;
    border-left: 3px solid #00bfff;
    border-radius: 8px;
    padding: 24px 28px;
    margin-bottom: 22px;
}

.dbmig-sim-briefing-title {
    color: #00bfff;
    font-size: 1.05rem;
    font-weight: 700;
    margin-bottom: 12px;
    letter-spacing: 0.04em;
    text-transform: uppercase;
}

.dbmig-sim-briefing-text {
    color: #c8d1e0;
    line-height: 1.65;
    font-size: 0.95rem;
}

.dbmig-sim-briefing-text b { color: #00ff88; font-weight: 700; }
.dbmig-sim-briefing-text i { color: #ffd166; font-style: normal; }
.dbmig-sim-briefing-text code {
    background: #0a0f1e;
    color: #00ff88;
    padding: 2px 6px;
    border-radius: 3px;
    font-family: 'SF Mono', Monaco, 'Cascadia Code', Consolas, monospace;
    font-size: 0.88em;
    border: 1px solid #1f2d3d;
}

.dbmig-sim-controls {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 24px 26px;
    margin-bottom: 22px;
}

.dbmig-sim-controls h3 {
    color: #00ff88;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.10em;
    margin-bottom: 18px;
    font-weight: 700;
}

.dbmig-sim-controls label {
    color: #c8d1e0;
    font-size: 0.95rem;
    margin-bottom: 10px;
    display: block;
    font-weight: 500;
}

.dbmig-sim-controls select,
.dbmig-sim-controls input[type="number"],
.dbmig-sim-controls input[type="text"] {
    background: #0a0f1e;
    border: 1px solid #2d3f55;
    color: #e0e6f0;
    border-radius: 4px;
    padding: 10px 14px;
    width: 100%;
    font-size: 0.95rem;
    margin-bottom: 18px;
    transition: border-color 0.2s ease, box-shadow 0.2s ease;
    font-family: inherit;
}

.dbmig-sim-controls select:focus,
.dbmig-sim-controls input:focus {
    outline: none;
    border-color: #00ff88;
    box-shadow: 0 0 0 2px rgba(0,255,136,0.18);
}

.dbmig-sim-controls select option {
    background: #111827;
    color: #e0e6f0;
    padding: 6px;
}

.dbmig-sim-button-row {
    display: flex;
    gap: 10px;
    flex-wrap: wrap;
    margin-top: 4px;
}

.dbmig-sim-controls .btn {
    padding: 10px 22px;
    font-weight: 600;
    letter-spacing: 0.04em;
    border-radius: 4px;
    border: 1px solid transparent;
    transition: all 0.2s ease;
}

.dbmig-sim-controls .btn-primary {
    background: #00ff88;
    border-color: #00ff88;
    color: #0a0f1e;
}

.dbmig-sim-controls .btn-primary:hover {
    background: #00cc6e;
    border-color: #00cc6e;
    color: #0a0f1e;
    box-shadow: 0 0 12px rgba(0,255,136,0.4);
}

.dbmig-sim-controls .btn-outline-secondary {
    color: #9ca3af;
    border-color: #2d3f55;
    background: transparent;
}

.dbmig-sim-controls .btn-outline-secondary:hover {
    color: #e0e6f0;
    border-color: #70829a;
    background: #0a0f1e;
}

.dbmig-sim-feedback {
    background: rgba(0,191,255,0.05);
    border: 1px solid rgba(0,191,255,0.3);
    border-left: 4px solid #00bfff;
    padding: 18px 22px;
    border-radius: 6px;
    margin-bottom: 22px;
    color: #c8d1e0;
    line-height: 1.55;
    font-size: 0.93rem;
}

.dbmig-sim-feedback.correct {
    background: rgba(0,255,136,0.06);
    border-color: rgba(0,255,136,0.35);
    border-left-color: #00ff88;
}

.dbmig-sim-feedback.incorrect {
    background: rgba(255,107,53,0.06);
    border-color: rgba(255,107,53,0.35);
    border-left-color: #ff6b35;
}

.dbmig-sim-feedback b { color: #00ff88; }
.dbmig-sim-feedback.incorrect b { color: #ff6b35; }
.dbmig-sim-feedback code {
    background: #0a0f1e;
    color: #00ff88;
    padding: 2px 6px;
    border-radius: 3px;
    font-family: 'SF Mono', Monaco, 'Cascadia Code', Consolas, monospace;
    font-size: 0.88em;
    border: 1px solid #1f2d3d;
}
.dbmig-sim-feedback i { color: #ffd166; font-style: normal; }

.dbmig-sim-chart-wrap {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px;
    margin-bottom: 22px;
    height: 360px;
    position: relative;
}

.dbmig-sim-history-wrap {
    background: #111827;
    border: 1px solid #1f2d3d;
    border-radius: 8px;
    padding: 22px;
    margin-bottom: 22px;
}

.dbmig-sim-history-wrap h3 {
    color: #00ff88;
    font-size: 0.85rem;
    text-transform: uppercase;
    letter-spacing: 0.10em;
    margin-bottom: 14px;
    font-weight: 700;
}

.dbmig-sim-history-wrap table {
    color: #c8d1e0;
    background: transparent;
    margin-bottom: 0;
    font-size: 0.88rem;
}

.dbmig-sim-history-wrap table th {
    color: #00bfff;
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.10em;
    border-color: #2d3f55;
    padding: 10px 12px;
    background: #0d1525;
    font-weight: 700;
}

.dbmig-sim-history-wrap table td {
    border-color: #1f2d3d;
    padding: 10px 12px;
    vertical-align: middle;
}

.dbmig-sim-history-wrap .table-striped tbody tr:nth-of-type(odd) {
    background-color: rgba(0,191,255,0.03);
}

.dbmig-sim-history-wrap .table-striped tbody tr:hover {
    background-color: rgba(0,255,136,0.05);
}

@media (max-width: 768px) {
    .dbmig-sim-container { padding: 16px; }
    .dbmig-sim-header { padding: 18px 22px; }
    .dbmig-sim-container .dbmig-sim-header h1 { font-size: 1.25rem; }
    .dbmig-sim-kpi-value { font-size: 1.6rem; }
    .dbmig-sim-controls { padding: 18px; }
    .dbmig-sim-button-row .btn { width: 100%; margin-bottom: 4px; }
    .dbmig-sim-period-bar { flex-wrap: wrap; }
    .dbmig-sim-score-badge { margin-top: 6px; }
}

/* a11y: visible keyboard focus on every interactive control */
.dbmig-sim-container select:focus-visible,
.dbmig-sim-container input:focus-visible,
.dbmig-sim-container button:focus-visible {
    outline: 3px solid #4ade80;
    outline-offset: 2px;
}

.dbmig-sim-complete {
    margin: 18px 0 24px 0;
    padding: 20px 22px;
    border: 1px solid #1e4436;
    border-radius: 10px;
    background: #0d1b18;
    color: #e2e8f0;
}
.dbmig-sim-complete h3 { margin: 0 0 6px 0; color: #4ade80; }
.dbmig-sim-complete-band { margin: 0 0 10px 0; font-weight: 600; color: #a7f3d0; }
.dbmig-sim-complete-kpis { margin: 0 0 12px 18px; padding: 0; }
.dbmig-sim-complete-kpis li { margin: 2px 0; }
.dbmig-sim-done-score { font-weight: 600; color: #4ade80; }

@media (prefers-reduced-motion: reduce) {
    .dbmig-sim-container *,
    .dbmig-sim-container *::before,
    .dbmig-sim-container *::after {
        animation-duration: 0.001ms !important;
        animation-iteration-count: 1 !important;
        transition-duration: 0.001ms !important;
        scroll-behavior: auto !important;
    }
}

js:
/* EQIL guard 1.1 (2026-09-29). Shared block, identical in every sim except SEED.
   1. Choice decisions start with no option selected and a seeded option order
      (MODE blank: empty selection, original order, for sims that address options by index).
   2. Render timers set while scoring a round wait until the period has advanced.
   3. getHint reads the round that was just scored.
   4. Where the runtime has no eventBus (Open player), a minimal one emits the platform events.
   5. Summary labels and insights returned as translation keys are translated for the platform default debrief.
   6. The framework t() is bound to its instance, so sims that copy it into a local variable keep working.
   7. (1.1) Checkboxes the view ticks by default start unticked until the player ticks them. A restored or
      resumed game keeps its ticks, disabled boxes are left alone, and a tick the player made is never cleared.
   Review: Express/testing/eqil_reports/2026-09/EQIL_Portfolio_Finding_open-catalog-review_2026-09-28.md */
var __eqilGuard = (function () {
    var SEED = "1381";
    var MODE = "";   // blank mode: the sim addresses options by position, so no inserted placeholder and no shuffle
    var TXT = {
        en: ["Choose an option", "Choose an option in every decision before continuing."],
        es: ["Elige una opción", "Elige una opción en cada decisión antes de continuar."],
        ca: ["Tria una opció", "Tria una opció a cada decisió abans de continuar."],
        pt: ["Escolha uma opção", "Escolha uma opção em cada decisão antes de continuar."],
        fr: ["Choisissez une option", "Choisissez une option pour chaque décision avant de continuer."]
    };
    var LEVEL = ["none", "low", "medium", "moderate", "high", "very ", "minimal", "maximum", "conservative", "aggressive",
        "ningun", "bajo", "baja", "medio", "media", "moderad", "alto", "alta", "muy ", "mínim", "máxim", "conservador", "agresiv"];
    var later = window.setTimeout.bind(window);
    var submitted = null;
    var lastRound = null;
    var queued = false;
    var styled = false;
    var groups = {};
    var restoring = false;
    var resumed = false;

    var bus = null;
    function sim() { return window.mySimulation || null; }
    function miniBus() {
        var h = {};
        return {
            on: function (n, f) { (h[n] = h[n] || []).push(f); },
            off: function (n, f) { var a = h[n] || [], k = a.indexOf(f); if (k >= 0) { a.splice(k, 1); } },
            emit: function (n, d) { var a = (h[n] || []).slice(); for (var i = 0; i < a.length; i++) { try { a[i](d); } catch (e) {} } }
        };
    }
    function polyfill(f) {
        if (!f || f.eventBus) { return; }
        bus = miniBus();
        f.eventBus = bus;
        if (typeof f.undo === "function") {
            var u = f.undo;
            f.undo = function () { var r = u.apply(this, arguments); bus.emit("period:undone", this.state); return r; };
        }
        if (typeof f.setLang === "function") {
            var sl = f.setLang;
            f.setLang = function (l) {
                var r = sl.apply(this, arguments);
                bus.emit("language:changed", { lang: l });
                try { document.dispatchEvent(new CustomEvent("express:langchanged", { detail: { lang: l } })); } catch (e) {}
                return r;
            };
        }
    }
    function announce(state, res) {
        if (!bus || !state) { return; }
        var p0 = state.currentPeriod, t0 = Date.now();
        (function check() {
            if (String(state.currentPeriod) !== String(p0) || Date.now() - t0 > 4000) { bus.emit("period:submitted", { results: res, period: p0 }); }
            else { later(check, 40); }
        })();
    }
    function lang() {
        var l = "";
        try { if (window.vcI18n && window.vcI18n._lang) { l = window.vcI18n._lang; } } catch (e) {}
        try { if (!l && sim() && sim().lang) { l = sim().lang; } } catch (e) {}
        if (!l) { l = document.documentElement.lang || "en"; }
        l = String(l).toLowerCase().slice(0, 2);
        return TXT[l] ? l : "en";
    }
    function roundKey() { var f = sim(); return f && f.state ? String(f.state.currentPeriod) : ""; }
    function hash(s) {
        var h = 2166136261;
        for (var i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = Math.imul(h, 16777619); }
        return h >>> 0;
    }
    function rand(seed) {
        var a = seed;
        return function () {
            a = (a + 0x6D2B79F5) | 0;
            var t = Math.imul(a ^ (a >>> 15), 1 | a);
            t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
            return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
        };
    }
    function permute(items, key) {
        var r = rand(hash(key)), a = items.slice();
        for (var i = a.length - 1; i > 0; i--) { var j = Math.floor(r() * (i + 1)); var t = a[i]; a[i] = a[j]; a[j] = t; }
        return a;
    }
    function gameKey(name, values) {
        var f = sim(), g = f && f.state && f.state.gameId;
        return SEED + "|" + (g || "") + "|" + name + "|" + values.join(",");
    }
    function shown(el) {
        for (var n = el; n && n.nodeType === 1; n = n.parentElement) {
            if (n.hidden || n.id === "usfp-overlay") { return false; }
            var cs = window.getComputedStyle ? window.getComputedStyle(n) : null;
            if (cs && (cs.display === "none" || cs.visibility === "hidden")) { return false; }
        }
        return true;
    }
    function skipped(el) {
        if (el.getAttribute("data-eqil-skip") !== null) { return true; }
        return !!(el.closest && el.closest("#usfp-overlay"));
    }
    function ordinal(texts, values) {
        var nv = 0, nt = 0, lv = 0;
        for (var i = 0; i < texts.length; i++) {
            var v = String(values[i]).trim(), t = String(texts[i]).trim().toLowerCase(), c = t.charAt(0);
            if (v !== "" && !isNaN(Number(v))) { nv++; }
            if ((c >= "0" && c <= "9") || c === "$" || c === "€" || c === "£" || c === "+" || c === "-" || t.indexOf("%") >= 0) { nt++; }
            for (var k = 0; k < LEVEL.length; k++) { if (t.indexOf(LEVEL[k]) === 0) { lv++; break; } }
        }
        return nv === texts.length || nt * 2 >= texts.length || lv >= 2;
    }
    var PH_WORDS = ["select", "selec", "elig", "elij", "escog", "escoj", "choose", "pick one", "tria ", "escolh", "choisi"];
    function isPlaceholder(o) {
        if (o.value === "") { return true; }
        var t = String(o.textContent || "").trim().toLowerCase(), c = t.charAt(0), k;
        if (!(c === "-" || c === "—" || c === "–" || c === "." || c === "…")) { return false; }
        for (k = 0; k < PH_WORDS.length; k++) { if (t.indexOf(PH_WORDS[k]) >= 0) { return true; } }
        for (k = 0; k < t.length; k++) { if ("-—–.… ".indexOf(t.charAt(k)) < 0) { return false; } }
        return true;
    }
    function clear(sel, ph) {
        if (ph) { sel.value = ph.value; } else { sel.selectedIndex = -1; }
    }
    function hasValue(sel, v) {
        for (var i = 0; i < sel.options.length; i++) { if (sel.options[i].value === v) { return true; } }
        return false;
    }

    function doSelect(sel, roundChanged) {
        var opts = sel.options, real = [], ph = null, fresh = false, i;
        for (i = 0; i < opts.length; i++) {
            if (isPlaceholder(opts[i])) { if (!ph) { ph = opts[i]; } continue; }
            real.push(opts[i]);
            if (!opts[i].__eqil) { fresh = true; }
        }
        if (real.length < 2) { return; }
        sel.__eqilManaged = true;
        var none = ph ? ph.value : "";
        if (fresh) {
            var before = sel.value, prev = sel.__eqilLast, wasUser = sel.__eqilUser && !roundChanged;
            if (!ph && MODE !== "blank") {
                ph = document.createElement("option");
                ph.value = "";
                ph.disabled = true;
                ph.setAttribute("data-eqil-ph", "1");
                sel.insertBefore(ph, sel.firstChild);
            }
            var texts = [], values = [];
            for (i = 0; i < real.length; i++) { real[i].__eqil = true; texts.push(real[i].textContent); values.push(real[i].value); }
            if (MODE !== "blank" && !sel.querySelector("optgroup") && !ordinal(texts, values)) {
                var order = permute(real, gameKey(sel.id || sel.name || "", values));
                for (i = 0; i < order.length; i++) { sel.appendChild(order[i]); }
            }
            sel.__eqilDef = before;
            sel.__eqilPh = ph ? ph.value : "";
            if (wasUser && prev && prev !== sel.__eqilPh && hasValue(sel, prev)) { sel.value = prev; }
            else if (shown(sel)) { clear(sel, ph); sel.__eqilUser = false; }
            else { sel.value = before; sel.__eqilUser = false; }
        } else {
            if (roundChanged) { sel.__eqilUser = false; }
            if (!sel.__eqilUser && sel.value !== none && sel.value === sel.__eqilDef && shown(sel)) { clear(sel, ph); }
        }
        if (ph && ph.getAttribute("data-eqil-ph") !== null) {
            var label = "— " + TXT[lang()][0] + " —";
            if (ph.textContent !== label) { ph.textContent = label; }
        }
        if (!sel.__eqilBound) {
            sel.__eqilBound = true;
            sel.addEventListener("change", function () {
                sel.__eqilUser = true;
                sel.__eqilLast = sel.value;
                sel.classList.remove("eqil-missing");
            });
        }
        sel.__eqilLast = sel.value;
    }

    function checkedValue(els) {
        for (var i = 0; i < els.length; i++) { if (els[i].checked) { return els[i].value; } }
        return null;
    }
    function setRadio(els, v) { for (var i = 0; i < els.length; i++) { els[i].checked = (v !== null && els[i].value === v); } }
    function radioItems(els) {
        var box = els[0].parentElement, i, ok;
        while (box) {
            ok = true;
            for (i = 0; i < els.length; i++) { if (!box.contains(els[i])) { ok = false; break; } }
            if (ok) { break; }
            box = box.parentElement;
        }
        if (!box) { return null; }
        var items = [];
        for (i = 0; i < els.length; i++) {
            var it = els[i];
            while (it && it.parentElement !== box) { it = it.parentElement; }
            if (!it || items.indexOf(it) >= 0) { return null; }
            items.push(it);
        }
        var kids = Array.prototype.slice.call(box.children), pos = items.map(function (x) { return kids.indexOf(x); }).sort(function (a, b) { return a - b; });
        for (i = 1; i < pos.length; i++) { if (pos[i] !== pos[i - 1] + 1) { return null; } }
        return { box: box, items: items, after: kids[pos[pos.length - 1]].nextSibling };
    }
    function doRadios(name, els, roundChanged) {
        if (els.length < 2) { return; }
        var g = groups[name] || (groups[name] = {}), fresh = false, i, vis = false;
        for (i = 0; i < els.length; i++) { if (!els[i].__eqil) { fresh = true; } if (shown(els[i])) { vis = true; } }
        g.els = els;
        var cur = checkedValue(els);
        if (fresh) {
            var wasUser = g.user && !roundChanged, texts = [], values = [];
            for (i = 0; i < els.length; i++) {
                els[i].__eqil = true;
                values.push(els[i].value);
                var lab = els[i].closest ? els[i].closest("label") : null;
                texts.push(lab ? lab.textContent : els[i].value);
                if (!els[i].__eqilBound) {
                    els[i].__eqilBound = true;
                    els[i].addEventListener("change", function () {
                        g.user = true;
