                            { label: 'Audit Defensibility', data: [], borderColor: '#00bfff', backgroundColor: 'rgba(0,191,255,0.10)', borderWidth: 2.5, fill: false, tension: 0.25, pointRadius: 4, pointBackgroundColor: '#00bfff' },
                            { label: 'Query Performance',   data: [], borderColor: '#ff6b35', backgroundColor: 'rgba(255,107,53,0.10)', borderWidth: 2.5, fill: false, tension: 0.25, pointRadius: 4, pointBackgroundColor: '#ff6b35' },
