        }
        getChartData(state) {
            var ds = (state && state.domainState) || {};
            var board = ds.boardHistory || [];
            var labels = board.map(function(_, i) { return 'P' + (i + 1); });
            return {
                progressChart: {
                    labels: labels,
                    datasets: [
                        { data: board },
                        { data: ds.auditHistory || [] },
                        { data: ds.queryHistory || [] },
                        { data: ds.progressHistory || [] }
                    ]
                }
            };
        }
        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var correct = history.filter(function(r) { return r.results && r.results.correct; }).length;
            var total = history.length;
            var accuracy = total ? correct / total : 0;
            var lastResult = history[history.length - 1].results || {};

            // The graded number is the one the player watched all run: the Migration
            // Score badge, results.overallScore. The previous version banded on a
            // separate mean-of-four-dimensions figure, so the verdict could disagree
            // with the score on screen.
            var dimMean = ((lastResult.boardConfidence || 0) + (lastResult.auditDefensibility || 0) +
                           (lastResult.queryPerformance || 0) + (lastResult.migrationProgress || 0)) / 4;
            var overall = Math.round(lastResult.overallScore !== undefined ? lastResult.overallScore : dimMean);

            var perf = 'beginner';
            if (overall > 50) perf = 'apprentice';
            if (overall > 70) perf = 'solid';
            if (overall > 85) perf = 'excellent';

            var labels = {
                beginner: this._t('perf_beginner', 'Beginner'),
                apprentice: this._t('perf_apprentice', 'Apprentice'),
                solid: this._t('perf_solid', 'Solid'),
                excellent: this._t('perf_excellent', 'Excellent')
            };

            var insights = [];
            if (accuracy >= 0.85) {
                insights.push(this._t('insight_strong', ''));
            } else if (accuracy >= 0.55) {
                insights.push(this._t('insight_mixed', ''));
            } else {
                insights.push(this._t('insight_review', ''));
            }
            insights.push(this._t('insight_arc', ''));

            return {
                correct: correct,
                total: total,
                accuracy: accuracy,
                overallScore: overall,
                totalScore: overall,
                score: overall,
                composite: overall,
                finalScore: overall,
                dimensionMean: Math.round(dimMean),
                boardConfidence:    Math.round(lastResult.boardConfidence || 0),
                auditDefensibility: Math.round(lastResult.auditDefensibility || 0),
                queryPerformance:   Math.round(lastResult.queryPerformance || 0),
                migrationProgress:  Math.round(lastResult.migrationProgress || 0),
                performance: perf,
                performanceKey: perf,
                performanceLabel: labels[perf],
                insights: insights
            };
        }

        formatCompletionMessage(summary) {
            var s = summary || {};
            var rows = [
                [this._t('kpi_board', 'Board confidence'), s.boardConfidence],
                [this._t('kpi_audit', 'Audit defensibility'), s.auditDefensibility],
                [this._t('kpi_query', 'Query performance'), s.queryPerformance],
                [this._t('kpi_progress', 'Migration progress'), s.migrationProgress]
            ];
            var parts = [];
            parts.push('<div class="dbmig-sim-complete">');
            parts.push('<h3>' + this._t('done_title', 'Migration complete') + '</h3>');
            parts.push('<p class="dbmig-sim-complete-band">' + (s.performanceLabel || '')
                + ' &middot; ' + (s.overallScore || 0) + '/100</p>');
            parts.push('<p>' + this._t('score_label', 'Migration Score') + ': '
                + (s.correct || 0) + '/' + (s.total || 0) + '</p>');
            parts.push('<ul class="dbmig-sim-complete-kpis">');
            rows.forEach(function(r) { parts.push('<li>' + r[0] + ': ' + (r[1] || 0) + '</li>'); });
            parts.push('</ul>');
            (s.insights || []).forEach(function(i) { if (i) parts.push('<p>' + i + '</p>'); });
            parts.push('</div>');
            return parts.join('');
        }


        getHint(state, results) {
            if (!results) return null;
            if (!results.correct) return window.mySimulation.t('hint_review');
            if (state.domainState.boardConfidence < 50) return window.mySimulation.t('hint_low_board');
            if (state.domainState.queryPerformance > 80 && state.domainState.auditDefensibility < 60) {
                return window.mySimulation.t('hint_audit_gap');
            }
            return null;
        }

        getHistoryTableConfig() {
            return [
                { key: 'results.roundLabel',       label: 'Round',  i18nKey: 'col_round'   },
                { key: 'results.answer',           label: 'Choice', i18nKey: 'col_answer'  },
                { key: 'results.correct',          label: 'OK',     i18nKey: 'col_correct', formatter: function(v) { return v ? '✅' : '❌'; } },
                { key: 'results.boardConfidence',  label: 'Board',  i18nKey: 'col_board',   formatter: function(v) { return Math.round(v); } },
                { key: 'results.queryPerformance', label: 'Query',  i18nKey: 'col_query',   formatter: function(v) { return Math.round(v); } },
                { key: 'results.overallScore',     label: 'Score',  i18nKey: 'col_score',   formatter: function(v) { return Math.round(v) + '/100'; } }
            ];
        }

        getPresets() { return null; }
        _updateBriefing(state) {
            var total = this.SCENARIOS.length;
            var period = (state && state.currentPeriod) ? state.currentPeriod : 1;
            var t = function(k) {
                return (window.mySimulation && window.mySimulation.t) ? window.mySimulation.t(k) : k;
            };
            var controls = document.getElementById('decisionControls');
            var done = document.getElementById('runCompletePanel');

            if (period > total) {
                // Terminal state. The previous version clamped the index and left the
                // select and Submit live on the last scenario forever.
                if (controls) controls.style.display = 'none';
                if (done) {
                    done.style.display = 'block';
                    var ds = (state && state.domainState) || {};
                    done.innerHTML = '<h3>' + this._t('done_title', 'Migration complete') + '</h3>'
                        + '<p>' + this._t('done_body', 'Every decision is locked. Your migration design is on the record.') + '</p>'
                        + '<p class="dbmig-sim-done-score">' + this._t('score_label', 'Migration Score')
                        + ': ' + (ds.overallScore || 0) + '/100</p>';
                }
                var rl = document.getElementById('roundLabel');
                if (rl) rl.textContent = this._t('done_title', 'Migration complete');
                return;
            }

            if (controls) controls.style.display = '';
            if (done) done.style.display = 'none';

            var idx = Math.min(period - 1, total - 1);
            var scenario = this.SCENARIOS[idx];

            var titleEl = document.getElementById('scenarioTitle');
            if (titleEl) titleEl.innerHTML = t(scenario.titleKey);

            var briefEl = document.getElementById('briefingText');
            if (briefEl) briefEl.innerHTML = t(scenario.briefKey);

            var questionEl = document.getElementById('questionLabel');
            if (questionEl) questionEl.innerHTML = t(scenario.questionKey);

            var sel = document.getElementById('answerSelect');
            var key = idx + ':' + this._lang();
            if (sel && this._renderedScenario !== key) {
                // Rebuild only on a genuine scenario or language change, so a stray
                // re-render can never disturb a selection the player has already made.
                var prev = sel.value;
                sel.innerHTML = '';
                var placeholder = document.createElement('option');
                placeholder.value = '';
                placeholder.textContent = '\u2014 ' + t('select_placeholder') + ' \u2014';
                sel.appendChild(placeholder);
                scenario.options.forEach(function(opt) {
                    var o = document.createElement('option');
                    o.value = opt.value;
                    var raw = t(opt.labelKey);
                    var div = document.createElement('div');
                    div.innerHTML = raw;
                    o.textContent = div.textContent;
                    sel.appendChild(o);
                });
                sel.value = (this._renderedScenario === null && prev) ? prev : '';
                this._renderedScenario = key;
            }

            var roundLabel = document.getElementById('roundLabel');
            if (roundLabel) roundLabel.textContent = t('round_label') + ' ' + scenario.round;
        }


        _renderFeedback(state) {
            var fbPanel = document.getElementById('feedbackPanel');
            var fbText = document.getElementById('feedbackText');
            if (!fbPanel || !fbText) return;
            var key = state.domainState && state.domainState.lastFeedbackKey;
            if (!key) {
                fbPanel.style.display = 'none';
                return;
            }
            var correct = !!(state.domainState && state.domainState.lastFeedbackCorrect);
            var t = window.mySimulation && window.mySimulation.t ? window.mySimulation.t.bind(window.mySimulation) : function(k){ return k; };
            fbPanel.style.display = 'block';
            fbPanel.classList.remove('correct', 'incorrect');
            fbPanel.classList.add(correct ? 'correct' : 'incorrect');
            fbText.innerHTML = (correct ? '✅ ' : '⚠️ ') + t(key);
        }

        getTranslations() {
            return {
                en: {
                    title:               `From Spreadsheet to Database`,
                    subtitle:            `Helio Verde Beverages · Migrate the 1.4M-row workbook`,
                    period_label:        `Period`,
                    period_of:           `of`,
                    round_label:         `Round`,
                    score_label:         `Migration Score`,
                    select_placeholder:  `Select your answer`,
                    kpi_board:           `Board Confidence`,
                    kpi_audit:           `Audit Defensibility`,
                    kpi_query:           `Query Performance`,
                    kpi_progress:        `Migration Progress`,
                    decisions_heading:   `Your Decision`,
                    question_label:      `Select the best answer`,
                    submit_btn:          `Submit Decision`,
                    undo_btn:            `Undo Last Period`,
                    history_heading:     `Decision History`,
                    warn_no_answer:      `Please select an answer before submitting.`,

                    s1_title: `Round 1 · Failure Mode 1 — Performance`,
                    s1_brief: `<b>Tuesday afternoon at Helio Verde S&amp;OP.</b> The 1.4M-row master workbook took <b>6 min 12 s</b> to open on Marta's 16GB laptop, <b>9 min 40 s</b> on the 8GB machines.<br><br>SUMIFS across 1.4M rows: <b>38 s</b> first run, <b>11 s</b> on recalc. Pivot refresh: <b>70 s</b>. The CFO calls and asks one question — what is actually slowing this down?`,
                    s1_q:     `What is the binding constraint on Excel performance at this scale?`,
                    s1_o1:    `Disk I/O — the .xlsx file is too large to read fast`,
                    s1_o2:    `Network — SharePoint co-authoring sync is slow`,
                    s1_o3:    `RAM exhaustion plus whole-workbook recalc — it slows to minutes at this size`,
                    s1_o4:    `GPU — Excel does not use hardware acceleration`,
                    s1_fb_ok: `<b>Correct.</b> Excel loads the entire workbook into RAM; once footprint exceeds ~1.5GB, swapping kicks in. Recalculation of the whole workbook slows to minutes at this size — extra cores help little once memory is the bottleneck. Performance pain begins ~500K rows; the .xlsx ceiling is <b>1,048,576 rows</b> (= 2²⁰), set in Excel 2007 and unchanged since.`,
                    s1_fb_no: `<b>Not quite.</b> Disk I/O and network are secondary. The real constraint is <i>RAM exhaustion plus whole-workbook recalc</i> — Excel was not designed for million-row workloads, even on modern multi-core CPUs. Performance pain begins ~500K rows; the .xlsx ceiling is 1,048,576 rows (= 2²⁰).`,

                    s2_title: `Round 1 · Failure Mode 2 — Concurrency`,
                    s2_brief: `Twelve analysts have the workbook open via SharePoint co-authoring.<br><br>Marta types <i>Mercado del Sur</i> into B47291. Eleven minutes later Pedro applies a filter that re-sorts the sheet. SharePoint resolves Pedro's re-sort <i>after</i> Marta's edit but in a different cell-coordinate space. Marta's change ends up overwriting an unrelated row. Three minutes later Ana autosaves a pivot referencing the now-corrupted master range.<br><br><b>Nobody can tell the CFO what the Mercado Sur Q1 revenue actually is.</b>`,
                    s2_q:     `What is the architectural root cause of this corruption?`,
                    s2_o1:    `User error — Marta should have locked the cell before editing`,
                    s2_o2:    `Spreadsheets were architected for one editor; concurrent editing is grafted on, and the seams show under structural ops (sort, filter, formula update)`,
                    s2_o3:    `A SharePoint bug — file a ticket with Microsoft`,
                    s2_o4:    `Missing backup discipline — restore from yesterday and forbid Tuesday edits`,
                    s2_fb_ok: `<b>Correct.</b> SharePoint co-authoring resolves disjoint cell edits cleanly. It cannot reconcile edits with structural operations because there is no transactional consistency model and no row-level locking. This is architectural, not behavioural — no amount of process discipline fixes it.`,
                    s2_fb_no: `<b>Not quite.</b> The issue is architectural — spreadsheets were built for a <i>single editor</i>; multi-editor support is layered on and breaks under interleaved structural operations (sort, filter, formula update). User training, backups, and Microsoft tickets do not fix the missing transactional consistency model.`,

                    s3_title: `Round 1 · Failure Modes 3 &amp; 4 — Integrity &amp; Audit`,
                    s3_brief: `The dashboard surfaces <b>47 distinct spellings</b> of <i>Mercado Sur</i> in the customer column. The SKU column has <b>312</b> strings for 280 actual products. Promotion codes: <b>58</b> for 40 active. Territory: <b>31</b> for 22.<br><br>Then the CFO asks: the Q4 promotion ROI report showed Mercado Sur at +14% lift; the January board pack reported +9%. Which is right?<br><br>Autosave history goes back 30 days. The November snapshot is gone. There is no record of who edited what when.<br><br>The CFO wants the migration trigger rule for the board.`,
                    s3_q:     `Which rule should trigger migration off Excel?`,
                    s3_o1:    `Only when the workbook crosses 1,048,576 rows — the Excel hard ceiling`,
                    s3_o2:    `Only when performance becomes unacceptable`,
                    s3_o3:    `<b>Any one</b> of the four canonical failure modes biting hard — performance, concurrency, integrity, or auditability — independent of row count`,
                    s3_o4:    `Never — Excel works fine if you have discipline`,
                    s3_fb_ok: `<b>Correct.</b> The threshold is not a row count. The decision rubric: &lt;100K rows + one editor → Excel is fine; 100K–500K + few editors → Excel with discipline; &gt;500K rows OR shared editing OR audit requirement OR integrity-critical → migrate. Helio Verde crossed all four thresholds simultaneously, which is why the leaked memo exists.`,
                    s3_fb_no: `<b>Not quite.</b> Row-count fixation is the most common error in this conversation. Many firms hit concurrency or integrity walls long before 1M rows; the Mercado Sur 47-spelling problem and the missing November snapshot do not wait for the .xlsx ceiling. The trigger is <i>any one</i> of the four canonical failure modes biting — not a magic row number.`,

                    s4_title: `Round 2 · Schema Decomposition`,
                    s4_brief: `The board approved the migration. The team is staring at the new PostgreSQL VM and the 1.4M-row workbook export. The instinct of the most senior analyst — <i>let's just import the workbook into one big <code>sales_data</code> table and start querying.</i><br><br>Pause. Round 1 said the spreadsheet had concurrency, integrity and auditability problems. <b>A schema is not a transcription of the spreadsheet — it is an act of design.</b> What is the right decomposition strategy?`,
                    s4_q:     `How should the schema be organised?`,
                    s4_o1:    `Single denormalised table — fastest to build, queries already work`,
                    s4_o2:    `Aggressive denormalisation for query speed — copy customer fields into every order line`,
                    s4_o3:    `3NF normalisation — separate master tables (customer, product, promotion, territory) and transactional tables (sales_order, order_line, invoice, payment) linked by foreign keys`,
                    s4_o4:    `Push to BCNF for every table, regardless of whether anomalies exist`,
                    s4_fb_ok: `<b>Correct.</b> The pragmatic OLTP rule is <b>aim for 3NF</b>. A single denormalised dump preserves all the integrity problems from Excel — the 47 spellings of Mercado Sur become 47 rows in one table. BCNF everywhere is academic over-engineering. The work is in decomposition into ~9 tables: customer, territory, product, promotion, sales_order, order_line, delivery, invoice, payment.`,
                    s4_fb_no: `<b>Not quite.</b> A one-table dump is a <i>faster way to be wrong</i> — the 47 spellings of Mercado Sur become 47 rows in a denormalised table, and the customer master is still uncontrolled. The pragmatic OLTP rule is <b>3NF</b>: master tables + transactional tables linked by foreign keys. BCNF everywhere is academic over-engineering.`,

                    s5_title: `Round 2 · Master Data &amp; Foreign Keys`,
                    s5_brief: `The team has the customer master table designed. Now the question — how to prevent the 47 spellings of Mercado Sur from recurring once the data is loaded?<br><br>Sales reps in the field type customer names freehand into the order form. Trade Marketing renames customers based on contract changes. Finance applies <i>doing business as</i> suffixes for tax purposes. Without a constraint, the master will fragment again within months.`,
                    s5_q:     `How should master-data integrity be enforced?`,
                    s5_o1:    `Document the canonical names in a Confluence page; trust analysts to follow it`,
                    s5_o2:    `Run a weekly deduplication script against the production data`,
                    s5_o3:    `Foreign key constraints — order.customer_id must reference an existing customer.customer_id; new customers go through a controlled add workflow with a single owner`,
                    s5_o4:    `Free-text customer field with a fuzzy-match validator`,
                    s5_fb_ok: `<b>Correct.</b> Referential integrity in machine-enforced form. The database refuses to accept an order whose <code>customer_id</code> does not exist in the customer table. Combined with master-data ownership (one approver, one workflow), this is the structural fix the spreadsheet could not deliver. The 47 spellings cannot reappear because the bad values are physically rejected at insert time.`,
                    s5_fb_no: `<b>Not quite.</b> Documentation, dedup scripts and fuzzy validators all rely on humans (or batch jobs) to catch errors after the fact — same failure surface as the spreadsheet. <b>Foreign key constraints</b> make the database refuse the bad insert at write time. That is referential integrity in machine-enforced form, and it is the structural fix the spreadsheet could not deliver.`,

                    s6_title: `Round 2 · Indexing Strategy`,
                    s6_brief: `Schema is loaded. First analyst query — <i>revenue by customer for Q1 2025</i> — took <b>14 seconds</b>. The team is confused; the database was supposed to be fast.<br><br>Recall the arithmetic: for a 1M-row table, log₂(1,000,000) ≈ 20, so an indexed lookup touches ~20 nodes vs ~1,000,000 for a full scan — a <b>~50,000× speedup</b>. Under-indexing is the single most common rookie mistake in relational databases.`,
                    s6_q:     `Which columns should the team index?`,
                    s6_o1:    `Index nothing — modern databases handle it automatically`,
                    s6_o2:    `Index every column — disk is cheap, queries should always be fast`,
                    s6_o3:    `Index only primary keys — the engine already does this`,
                    s6_o4:    `Index primary keys (auto), every foreign key, and any column appearing in WHERE / JOIN / ORDER BY — invoice_date, order_date, payment_date are obvious candidates`,
                    s6_fb_ok: `<b>Correct.</b> Indexing PK + FK + filter/join columns is the default discipline. With <code>(invoice_date)</code> indexed, the Q1 revenue query drops from 14 seconds to <b>~120 ms</b> — a ~120× speedup on this dataset. Cost is some write overhead and disk space; benefit is the O(log n) vs O(n) gap. Add the index, watch the query collapse.`,
                    s6_fb_no: `<b>Not quite.</b> Indexing nothing condemns every query to a full scan; indexing everything wastes write cycles on columns nobody filters; PK-only ignores the FKs and date columns the analysts actually filter on. The discipline: <b>PK + every FK + every column in WHERE / JOIN / ORDER BY</b>. Add the missing index, the query drops from 14 s to ~120 ms.`,

                    s7_title: `Round 3 · OLTP vs OLAP`,
                    s7_brief: `Six months in, the OLTP database is humming. Then the BI team complains — every dashboard query joins seven tables and runs slowly. The S&amp;OP analysts want pre-aggregated marts; the data engineering team is purist about 3NF.<br><br>Two architectural worlds are colliding. The schema you built is OLTP — optimised for <i>writing</i> orders correctly. Analytics is a different workload — read-heavy aggregations across millions of rows, where shallow joins matter more than write efficiency.`,
                    s7_q:     `What is the right architecture for the analytical workload?`,
                    s7_o1:    `Use the OLTP 3NF schema for everything — joining seven tables is fine, hardware is cheap`,
                    s7_o2:    `Move the analytical workload to MongoDB — document stores handle aggregation better`,
                    s7_o3:    `Build a separate analytical layer with a Kimball star schema — central fact_sales_line surrounded by dimensions (customer_dim, product_dim, time_dim, territory_dim, promotion_dim); deliberately denormalised; loaded by ETL from the OLTP source`,
                    s7_o4:    `Export to CSV nightly and let analysts use Excel against the export`,
                    s7_fb_ok: `<b>Correct.</b> The pragmatic rule: <b>3NF for OLTP, star for OLAP</b>. Kimball &amp; Ross (2013) is the canonical reference. The fact table holds measurable quantities; dimension tables hold context. Reads are fast because joins are shallow and dimensional attributes are denormalised across the loaded marts. Write inefficiency is acceptable because the warehouse loads once per ETL cycle.`,
                    s7_fb_no: `<b>Not quite.</b> 3NF was right for OLTP and is wrong for OLAP — the workloads are architecturally different. Document stores do not solve the join problem; CSV-to-Excel reintroduces every Round 1 failure mode. The analytical answer is a Kimball star schema: one fact table, surrounding dimensions, deliberately denormalised. The two-architectures rule.`,

                    s8_title: `Round 3 · The Anti-Join Query`,
                    s8_brief: `Marketing wants the list of customers who ordered in 2023 but <i>not</i> in 2024 — the churn cohort.<br><br>The Excel approach: build two pivots, copy both into a new sheet, write a VLOOKUP that returns <code>#N/A</code> for missing matches, filter on <code>#N/A</code>. Five minutes of brittle work, and three places it can produce a wrong answer nobody notices.<br><br>SQL has a clean idiom for this. Pick the right one.`,
                    s8_q:     `Which SQL pattern returns customers in 2023 but not in 2024?`,
                    s8_o1:    `INNER JOIN on customer_id with date filters in the JOIN condition`,
                    s8_o2:    `SELECT COUNT(*) FROM 2023 minus SELECT COUNT(*) FROM 2024`,
                    s8_o3:    `LEFT JOIN ... WHERE NULL — keep customers with a 2023 row whose corresponding 2024 row does not exist`,
                    s8_o4:    `Two pivots and a VLOOKUP — same as Excel but in SQL`,
                    s8_fb_ok: `<b>Correct.</b> The classical anti-join pattern: <code>FROM customer c JOIN orders_2023 ... LEFT JOIN orders_2024 ... WHERE so24.order_id IS NULL</code>. Five lines of SQL for what Excel approximates in 40 minutes of brittle pivot-and-VLOOKUP work. Pivot tables aggregate; they do not subtract sets. The productivity cliff is qualitative, not incremental.`,
                    s8_fb_no: `<b>Not quite.</b> INNER JOIN returns the intersection, not the difference. Counting subtraction tells you size but not identity. Two pivots and a VLOOKUP recreates the Excel anti-pattern in SQL form. The idiom is <b>LEFT JOIN ... WHERE NULL</b> — the absent-match pattern that pivot tables fundamentally cannot express because they aggregate, they do not subtract sets.`,

                    s9_title: `Round 3 · The Tier Decision`,
                    s9_brief: `Final question for the board. The CFO needs a one-line recommendation she can defend. Five tiers on the table:<br><br><b>(a)</b> Excel-only · ~€500/yr · current state, collapses at scale<br><b>(b)</b> Excel + Microsoft Access · ~€500/yr · Access caps at ~few M rows; declining toolchain<br><b>(c)</b> PostgreSQL on a small VM · ~€1,200/yr · strong; weeks to deploy<br><b>(d)</b> Cloud-hosted relational (Aurora / Cloud SQL / Azure SQL) · ~€6K–€18K/yr · managed, audit-ready<br><b>(e)</b> Full modern data stack (cloud DW + dbt + Fivetran + BI) · ~€30K–€120K/yr · enterprise-grade<br><br>Helio Verde: ~€380M revenue, 12 analysts, four months of sales churning monthly, SOX-defensible numbers required.`,
                    s9_q:     `What is the right tier for Helio Verde?`,
                    s9_o1:    `(a) Excel-only with stricter discipline — cheapest, no migration risk`,
                    s9_o2:    `(b) Excel + Access — bundled with Office, no extra licence`,
                    s9_o3:    `(c) PostgreSQL on a single VM — covers OLTP cleanly at low cost`,
                    s9_o4:    `(d) Cloud-hosted relational for OLTP cleanup PLUS (e) modern data stack for the analytical workload — the defensible answer at €380M revenue with audit requirements`,
